window.ScripturaLexicons.BDAG_PART_0332 = {"source":"BDAG","searchAnchorId":"bdag-search-anchor","entryAnchorId":"bdag-entry-anchor","rowsHtml":"<tr class=\"search-row\" data-dictionary=\"grego\" data-target=\"entry-bdag-0332-01\" data-source=\"BDAG\" data-search=\"στίγμα, ατος, τό substantivo neutro marca; estigma BDAG\" tabindex=\"0\"><td class=\"table-lemma greek\">στίγμα, ατος, τό</td><td>substantivo neutro</td><td>marca; estigma</td><td><span class=\"source-pill\">BDAG</span></td></tr>\n<tr class=\"search-row\" data-dictionary=\"grego\" data-target=\"entry-bdag-0332-02\" data-source=\"BDAG\" data-search=\"στιγμή, ῆς, ἡ substantivo feminino ponto; instante BDAG\" tabindex=\"0\"><td class=\"table-lemma greek\">στιγμή, ῆς, ἡ</td><td>substantivo feminino</td><td>ponto; instante</td><td><span class=\"source-pill\">BDAG</span></td></tr>\n<tr class=\"search-row\" data-dictionary=\"grego\" data-target=\"entry-bdag-0332-03\" data-source=\"BDAG\" data-search=\"στίλβω verbo brilhar; resplandecer BDAG\" tabindex=\"0\"><td class=\"table-lemma greek\">στίλβω</td><td>verbo</td><td>brilhar; resplandecer</td><td><span class=\"source-pill\">BDAG</span></td></tr>\n<tr class=\"search-row\" data-dictionary=\"grego\" data-target=\"entry-bdag-0332-04\" data-source=\"BDAG\" data-search=\"στοά, ᾶς, ἡ substantivo feminino pórtico BDAG\" tabindex=\"0\"><td class=\"table-lemma greek\">στοά, ᾶς, ἡ</td><td>substantivo feminino</td><td>pórtico</td><td><span class=\"source-pill\">BDAG</span></td></tr>\n<tr class=\"search-row\" data-dictionary=\"grego\" data-target=\"entry-bdag-0332-05\" data-source=\"BDAG\" data-search=\"στοιβάς remissão ver στιβάς BDAG\" tabindex=\"0\"><td class=\"table-lemma greek\">στοιβάς</td><td>remissão</td><td>ver στιβάς</td><td><span class=\"source-pill\">BDAG</span></td></tr>\n<tr class=\"search-row\" data-dictionary=\"grego\" data-target=\"entry-bdag-0332-06\" data-source=\"BDAG\" data-search=\"Στοϊκός adjetivo estoico BDAG\" tabindex=\"0\"><td class=\"table-lemma greek\">Στοϊκός</td><td>adjetivo</td><td>estoico</td><td><span class=\"source-pill\">BDAG</span></td></tr>\n<tr class=\"search-row\" data-dictionary=\"grego\" data-target=\"entry-bdag-0332-07\" data-source=\"BDAG\" data-search=\"στοιχεῖον, ου, τό substantivo neutro elementos; princípios fundamentais; espíritos elementares BDAG\" tabindex=\"0\"><td class=\"table-lemma greek\">στοιχεῖον, ου, τό</td><td>substantivo neutro</td><td>elementos; princípios fundamentais; espíritos elementares</td><td><span class=\"source-pill\">BDAG</span></td></tr>\n<tr class=\"search-row\" data-dictionary=\"grego\" data-target=\"entry-bdag-0332-08\" data-source=\"BDAG\" data-search=\"στοιχέω verbo seguir; conformar-se BDAG\" tabindex=\"0\"><td class=\"table-lemma greek\">στοιχέω</td><td>verbo</td><td>seguir; conformar-se</td><td><span class=\"source-pill\">BDAG</span></td></tr>\n<tr class=\"search-row\" data-dictionary=\"grego\" data-target=\"entry-bdag-0332-09\" data-source=\"BDAG\" data-search=\"στοῖχος, ου, ὁ substantivo masculino fileira; fiada BDAG\" tabindex=\"0\"><td class=\"table-lemma greek\">στοῖχος, ου, ὁ</td><td>substantivo masculino</td><td>fileira; fiada</td><td><span class=\"source-pill\">BDAG</span></td></tr>\n<tr class=\"search-row\" data-dictionary=\"grego\" data-target=\"entry-bdag-0332-10\" data-source=\"BDAG\" data-search=\"στολή, ῆς, ἡ substantivo feminino veste longa BDAG\" tabindex=\"0\"><td class=\"table-lemma greek\">στολή, ῆς, ἡ</td><td>substantivo feminino</td><td>veste longa</td><td><span class=\"source-pill\">BDAG</span></td></tr>\n<tr class=\"search-row\" data-dictionary=\"grego\" data-target=\"entry-bdag-0332-11\" data-source=\"BDAG\" data-search=\"στόμα, ατος, τό substantivo neutro boca; enunciação; fissura; fio BDAG\" tabindex=\"0\"><td class=\"table-lemma greek\">στόμα, ατος, τό</td><td>substantivo neutro</td><td>boca; enunciação; fissura; fio</td><td><span class=\"source-pill\">BDAG</span></td></tr>\n<tr class=\"search-row\" data-dictionary=\"grego\" data-target=\"entry-bdag-0332-12\" data-source=\"BDAG\" data-search=\"στόμαχος, ου, ὁ substantivo masculino estômago BDAG\" tabindex=\"0\"><td class=\"table-lemma greek\">στόμαχος, ου, ὁ</td><td>substantivo masculino</td><td>estômago</td><td><span class=\"source-pill\">BDAG</span></td></tr>\n<tr class=\"search-row\" data-dictionary=\"grego\" data-target=\"entry-bdag-0332-13\" data-source=\"BDAG\" data-search=\"στραγγαλιά, ᾶς, ἡ substantivo feminino nó BDAG\" tabindex=\"0\"><td class=\"table-lemma greek\">στραγγαλιά, ᾶς, ἡ</td><td>substantivo feminino</td><td>nó</td><td><span class=\"source-pill\">BDAG</span></td></tr>\n<tr class=\"search-row\" data-dictionary=\"grego\" data-target=\"entry-bdag-0332-14\" data-source=\"BDAG\" data-search=\"στραγγαλόω verbo estrangular; sufocar-se BDAG\" tabindex=\"0\"><td class=\"table-lemma greek\">στραγγαλόω</td><td>verbo</td><td>estrangular; sufocar-se</td><td><span class=\"source-pill\">BDAG</span></td></tr>\n<tr class=\"search-row\" data-dictionary=\"grego\" data-target=\"entry-bdag-0332-15\" data-source=\"BDAG\" data-search=\"στρατεία, ας, ἡ substantivo feminino expedição; campanha militar BDAG\" tabindex=\"0\"><td class=\"table-lemma greek\">στρατεία, ας, ἡ</td><td>substantivo feminino</td><td>expedição; campanha militar</td><td><span class=\"source-pill\">BDAG</span></td></tr>\n<tr class=\"search-row\" data-dictionary=\"grego\" data-target=\"entry-bdag-0332-16\" data-source=\"BDAG\" data-search=\"στράτευμα, ατος, τό substantivo neutro exército; tropas BDAG\" tabindex=\"0\"><td class=\"table-lemma greek\">στράτευμα, ατος, τό</td><td>substantivo neutro</td><td>exército; tropas</td><td><span class=\"source-pill\">BDAG</span></td></tr>\n<tr class=\"search-row\" data-dictionary=\"grego\" data-target=\"entry-bdag-0332-17\" data-source=\"BDAG\" data-search=\"στρατεύω verbo servir no exército; combater BDAG\" tabindex=\"0\"><td class=\"table-lemma greek\">στρατεύω</td><td>verbo</td><td>servir no exército; combater</td><td><span class=\"source-pill\">BDAG</span></td></tr>\n<tr class=\"search-row\" data-dictionary=\"grego\" data-target=\"entry-bdag-0332-18\" data-source=\"BDAG\" data-search=\"στρατηγός, οῦ, ὁ substantivo masculino pretor; magistrado; capitão BDAG\" tabindex=\"0\"><td class=\"table-lemma greek\">στρατηγός, οῦ, ὁ</td><td>substantivo masculino</td><td>pretor; magistrado; capitão</td><td><span class=\"source-pill\">BDAG</span></td></tr>\n<tr class=\"search-row\" data-dictionary=\"grego\" data-target=\"entry-bdag-0332-19\" data-source=\"BDAG\" data-search=\"στρατιά, ᾶς, ἡ substantivo feminino exército; hoste BDAG\" tabindex=\"0\"><td class=\"table-lemma greek\">στρατιά, ᾶς, ἡ</td><td>substantivo feminino</td><td>exército; hoste</td><td><span class=\"source-pill\">BDAG</span></td></tr>\n<tr class=\"search-row\" data-dictionary=\"grego\" data-target=\"entry-bdag-0332-20\" data-source=\"BDAG\" data-search=\"στρατιώτης, ου, ὁ substantivo masculino soldado BDAG\" tabindex=\"0\"><td class=\"table-lemma greek\">στρατιώτης, ου, ὁ</td><td>substantivo masculino</td><td>soldado</td><td><span class=\"source-pill\">BDAG</span></td></tr>","cardsHtml":"<article class=\"entry-card\" id=\"entry-bdag-0332-01\" data-dictionary=\"grego\" hidden data-source=\"BDAG\"><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">στίγμα, ατος, τό</h1><div class=\"entry-meta\"><span>substantivo neutro</span></div></div><div class=\"source-tag\">BDAG</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Tradução integral</div><p class=\"entry-text\"><span class=\"greek\">στίγμα</span>, <span class=\"greek\">ατος</span>, <span class=\"greek\">τό</span> (<span class=\"greek\">στίζω</span> ‘tatuar’; Hdt. et al.; SIG 1168, 48; SSol 1:11) marca, estigma (não só o senhor imprimia um <span class=\"greek\">στίγμα</span> em seu escravo [Porphyr., Vi. Pyth. 15; Ps.-Phoc. 225.—Diod S 34 + 35 Fgm. 2, 32 exprime isso com <span class=\"greek\">τὰ</span> <span class=\"greek\">στίγματα</span> e 34 + 35, Fgm. 2, 1 com o singular <span class=\"greek\">στιγμή</span>], mas também a tatuagem religiosa desempenhava papel proeminente na Antiguidade: Hdt. 2, 113 <span class=\"greek\">στίγματα</span> <span class=\"greek\">ἱερά</span>; Lucian, Syr. Dea 59 <span class=\"greek\">στιγματηφορεῖν</span> em honra da deusa.—Dssm., B 265f [BS 349–52]; WHeitmüller, Heinrici Festschr. 1914, 47; FDölger, Sphragis 1911, 39ff, Ac I 1929, 66ff; II 1930, 102ff; III ’32, 257ff) <span class=\"greek\">τὰ</span> <span class=\"greek\">στ</span>. <span class=\"greek\">τοῦ</span> <span class=\"greek\">Ἰησοῦ</span> <span class=\"greek\">ἐν</span> <span class=\"greek\">τῷ</span> <span class=\"greek\">σώματί</span> <span class=\"greek\">μου</span> <span class=\"greek\">βαστάζω</span> trago em meu corpo as marcas de Jesus <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/GAL.6.17\" target=\"_blank\" rel=\"noopener noreferrer\">Gal 6:17</a> (Straub 59f); cf. AcPlCor 2:35 (Lucian, Catapl. 28: o homem inteiro [<span class=\"greek\">ὅλος</span>] está coberto de <span class=\"greek\">στίγματα</span>). Paulo muito provavelmente alude às feridas e cicatrizes que recebeu no serviço de Jesus (Plut., Mor. 566f e Hierocles 12, 445 col. 1 <span class=\"greek\">στίγματα</span> são as cicatrizes deixadas pela vara divina da disciplina).—JMoulton, ET 21, 1910, 283f; TCrafer, The Stoning of St. Paul at Lystra and the Epistle to the Galatians: Exp. 8th ser., 6, 1913, 375–84; OSchmitz, Die Christus-Gemeinschaft des Pls im Lichte seines Genetivgebrauchs 1924, 185ff; UWilcken, Deissmann Festschr. 1927, 8f; OHoltzmann, ZNW 30, ’31, 82f contra EHirsch, ibid. 29, 1930, 196f; EGüttgemanns, D. leidende Apostel, ’66, 126–35; HWindisch, Pls u. Christus ’34, 187; 251f.—CPJones, ‘Stigma’, Tatooing and Branding in Gr-Rom. Antiquity: JRS 77, ’87, 139–55. DELG s.v. <span class=\"greek\">στίζω</span>. M-M. EDNT. TW.</p></section></article>\n<article class=\"entry-card\" id=\"entry-bdag-0332-02\" data-dictionary=\"grego\" hidden data-source=\"BDAG\"><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">στιγμή, ῆς, ἡ</h1><div class=\"entry-meta\"><span>substantivo feminino</span></div></div><div class=\"source-tag\">BDAG</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Tradução integral</div><p class=\"entry-text\"><span class=\"greek\">στιγμή</span>, <span class=\"greek\">ῆς</span>, <span class=\"greek\">ἡ</span> inicialmente ‘ponto’ (Aristot. et al.), depois de algo bastante insignificante (Demosth. et al.), finalmente, especificamente do tempo, um instante (Plut.; M. Ant. 2, 17; Vett. Val. 131, 4; 239, 11 <span class=\"greek\">ἐν</span> <span class=\"greek\">στιγμῇ</span>; Is 29:5; 2 Macc 9:11), mais plenamente <span class=\"greek\">στιγμὴ</span> <span class=\"greek\">χρόνου</span> (Plut., Mor. 13b; Ps.-Plut., Mor. 104b de Demetr. Phaler., Fgm. 79 [ed. FWehrli ’49]) <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/LUK.4.5\" target=\"_blank\" rel=\"noopener noreferrer\">Lk 4:5</a>. Bibliografia, v. <span class=\"greek\">ῥιπή</span>.—DELG s.v. <span class=\"greek\">στίζω</span> 2. M-M. TW.</p></section></article>\n<article class=\"entry-card\" id=\"entry-bdag-0332-03\" data-dictionary=\"grego\" hidden data-source=\"BDAG\"><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">στίλβω</h1><div class=\"entry-meta\"><span>verbo</span></div></div><div class=\"source-tag\">BDAG</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Tradução integral</div><p class=\"entry-text\"><span class=\"greek\">στίλβω</span> emitir raios de luz, brilhar, resplandecer, de vestes (Hom. et al.; Pla., Phd. 59, 110d; Kaibel 918. Na LXX quase sempre do esplendor dos astros ou do brilho dos metais) na Transfiguração <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MRK.9.3\" target=\"_blank\" rel=\"noopener noreferrer\">Mk 9:3</a> (cf. OdeSol 11:14 <span class=\"greek\">ἔστιλβον</span> <span class=\"greek\">οἱ</span> <span class=\"greek\">ὀφθαλμοί</span> <span class=\"greek\">μου</span>; Hippiatr. I 287, 16 <span class=\"greek\">ὀφθαλμοὶ</span> <span class=\"greek\">γίνονται</span> <span class=\"greek\">στίλβοντες</span>). De uma porta <span class=\"greek\">ἔστιλβεν</span> <span class=\"greek\">ὑπὲρ</span> <span class=\"greek\">τὸν</span> <span class=\"greek\">ἥλιον</span> Hs 9, 2, 2 (cf. Chariton 1, 1, 5 <span class=\"greek\">στίλβων</span> <span class=\"greek\">ὥσπερ</span> <span class=\"greek\">ἀστήρ</span>).—DELG. M-M. TW.</p></section></article>\n<article class=\"entry-card\" id=\"entry-bdag-0332-04\" data-dictionary=\"grego\" hidden data-source=\"BDAG\"><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">στοά, ᾶς, ἡ</h1><div class=\"entry-meta\"><span>substantivo feminino</span></div></div><div class=\"source-tag\">BDAG</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Tradução integral</div><p class=\"entry-text\"><span class=\"greek\">στοά</span>, <span class=\"greek\">ᾶς</span>, <span class=\"greek\">ἡ</span> (Aristoph., Hdt. et al.; inscrições, papiros, LXX, Joseph.; empréstimo nos escritos rabínicos) uma colunata coberta, normalmente aberta de um lado, pórtico <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/JHN.5.2\" target=\"_blank\" rel=\"noopener noreferrer\">J 5:2</a> (Callicrates-Menecles [antes de 86 a.C.]: 370 Fgm. 1 Jac. <span class=\"greek\">κύκλῳ</span> <span class=\"greek\">τοῦ</span> <span class=\"greek\">λιμένος</span> <span class=\"greek\">στοαὶ</span> <span class=\"greek\">πέντε</span>). <span class=\"greek\">ἡ</span> <span class=\"greek\">στοὰ</span> <span class=\"greek\">τοῦ</span> <span class=\"greek\">Σολομῶνος</span> (cf. Nicol. Dam.: 90 Fgm. 130, 82 Jac. <span class=\"greek\">ἡ</span> <span class=\"greek\">Πομπηίου</span> <span class=\"greek\">στοά</span>) <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/JHN.10.23\" target=\"_blank\" rel=\"noopener noreferrer\">J 10:23</a> (Ps.-Pla., Eryx. 1, 392a <span class=\"greek\">περιπατοῦντες</span> <span class=\"greek\">ἐν</span> <span class=\"greek\">τῇ</span> <span class=\"greek\">στοᾷ</span> <span class=\"greek\">τοῦ</span> <span class=\"greek\">Διός</span>); cf. <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ACT.3.11\" target=\"_blank\" rel=\"noopener noreferrer\">Ac 3:11</a>; 5:12 (v. <span class=\"greek\">Σολομών</span>, final).—DELG. M-M.</p></section></article>\n<article class=\"entry-card\" id=\"entry-bdag-0332-05\" data-dictionary=\"grego\" hidden data-source=\"BDAG\"><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">στοιβάς</h1><div class=\"entry-meta\"><span>remissão</span></div></div><div class=\"source-tag\">BDAG</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Tradução integral</div><p class=\"entry-text\"><span class=\"greek\">στοιβάς</span> v. <span class=\"greek\">στιβάς</span>.</p></section></article>\n<article class=\"entry-card\" id=\"entry-bdag-0332-06\" data-dictionary=\"grego\" hidden data-source=\"BDAG\"><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">Στοϊκός</h1><div class=\"entry-meta\"><span>adjetivo</span></div></div><div class=\"source-tag\">BDAG</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Tradução integral</div><p class=\"entry-text\"><span class=\"greek\">Στοϊκός</span> (a forma <span class=\"greek\">Στωϊκός</span>, também atestada, é mais correta, mas não necessariamente a original [Just., Tat., Ath.; v. B-D-F §35, 1; Mlt-H. 73 prefere <span class=\"greek\">Στω</span>- como a original]), <span class=\"greek\">ή</span>, <span class=\"greek\">όν</span> estoico (Dionys. Hal., Comp. Verb. 2 p. 7, 3 Us.-Rad.; Diog. L. 4, 67; Philo; Jos., Vi. 12; Just.) <span class=\"greek\">Στοϊκοὶ</span> <span class=\"greek\">φιλόσοφοι</span>, mencionados ao lado dos epicureus <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ACT.17.18\" target=\"_blank\" rel=\"noopener noreferrer\">Ac 17:18</a>. MPohlenz, Die Stoa3 ’71/72; WBarclay, ET 72, ’61, 5 artigos passim, 164–294.—M-M.</p></section></article>\n<article class=\"entry-card\" id=\"entry-bdag-0332-07\" data-dictionary=\"grego\" hidden data-source=\"BDAG\"><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">στοιχεῖον, ου, τό</h1><div class=\"entry-meta\"><span>substantivo neutro</span></div></div><div class=\"source-tag\">BDAG</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Tradução integral</div><p class=\"entry-text\"><span class=\"greek\">στοιχεῖον</span>, <span class=\"greek\">ου</span>, <span class=\"greek\">τό</span> (desde Aristoph., X., Pla.; também BGU 959, 2) em nossa literatura somente no plural.</p>\n<p class=\"entry-text\">① componentes básicos de algo, elementos</p>\n<p class=\"entry-text\">ⓐ de substâncias subjacentes ao mundo natural, os elementos básicos dos quais tudo no mundo é feito e de que se compõe (Pla. et al.; PGM 4, 440; Wsd 7:17; 19:18; 4 Macc 12:13; Ath., R. 3 p. 51, 17), que desaparecerão na conflagração do mundo no fim dos tempos <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/2PE.3.10\" target=\"_blank\" rel=\"noopener noreferrer\">2 Pt 3:10</a>, 12 (Ath. 22, 3; bibliografia s.v. <span class=\"greek\">καυσόω</span>). Os quatro elementos do mundo (terra, ar, fogo, água) Hv 3, 13, 3 (cf. Diog. L. 7, 137 [Zenão, o estoico] <span class=\"greek\">ἔστι</span> <span class=\"greek\">δὲ</span> <span class=\"greek\">στοιχεῖον</span>, <span class=\"greek\">ἐξ</span> <span class=\"greek\">οὗ</span> <span class=\"greek\">πρώτου</span> <span class=\"greek\">γίνεται</span> <span class=\"greek\">τὰ</span> <span class=\"greek\">γινόμενα</span> <span class=\"greek\">καὶ</span> <span class=\"greek\">εἰς</span> <span class=\"greek\">ὸ̔</span> <span class=\"greek\">ἔσχατον</span> <span class=\"greek\">ἀναλύεται</span> … <span class=\"greek\">τὸ</span> <span class=\"greek\">πῦρ</span>, <span class=\"greek\">τὸ</span> <span class=\"greek\">ὕδωρ</span>, <span class=\"greek\">ὁ</span> <span class=\"greek\">ἀήρ</span>, <span class=\"greek\">ἡ</span> <span class=\"greek\">γῆ</span>; Plut., Mor. 875c; Philo, Cher. 127 <span class=\"greek\">τὰ</span> <span class=\"greek\">τέσσαρα</span> <span class=\"greek\">στοιχεῖα</span>; Jos., Ant. 3, 183.—JKroll, Die Lehren des Hermes Trismegistos 1914, 178ff; ESchweizer, JBL 107, ’88, 455–68). <span class=\"greek\">πῦρ</span> … <span class=\"greek\">ὕδωρ</span> … <span class=\"greek\">ἄλλο</span> <span class=\"greek\">τι</span> <span class=\"greek\">τῶν</span> <span class=\"greek\">στοιχείων</span> Dg 8:2; cf. 7:2 (v. b).</p>\n<p class=\"entry-text\">ⓑ de componentes básicos das constelações celestes, corpos celestes (Ar. 3, 2; Just., A II, 5, 2; Diog. L. 6. 102 <span class=\"greek\">τὰ</span> <span class=\"greek\">δώδεκα</span> <span class=\"greek\">στοιχεῖα</span> dos signos do zodíaco; POsl 4, 18 <span class=\"greek\">δώδεκα</span> <span class=\"greek\">στ</span>. <span class=\"greek\">τοῦ</span> <span class=\"greek\">οὐρανοῦ</span>; Ps.-Callisth. 13, 1.—PGM 4, 1303 a ‘Ursa’ é chamada de <span class=\"greek\">στοιχεῖον</span> <span class=\"greek\">ἄφθαρτον</span>.—Rtzst., Poim. 69ff, Herr der Grösse 13ff; Diels [v. abaixo] 53f; JvanWageningen, <span class=\"greek\">Τὰ</span> <span class=\"greek\">στοιχεῖα</span> <span class=\"greek\">τοῦ</span> <span class=\"greek\">κόσμου</span>: ThSt 35, 1917, 1–6; FColson, The Week 1926, 95ff) Dg 7:2.</p>\n<p class=\"entry-text\">ⓒ de coisas que constituem o fundamento da aprendizagem, princípios fundamentais (X., Mem. 2, 1, 1; Isocr. 2, 16; Plut., Lib. Educ. 16, 2; Just., A I, 60, 11) ou mesmo letras do alfabeto, rudimentos (Pla. et al.) <span class=\"greek\">τὰ</span> <span class=\"greek\">στ</span>. <span class=\"greek\">τῆς</span> <span class=\"greek\">ἀρχῆς</span> <span class=\"greek\">τῶν</span> <span class=\"greek\">λογίων</span> <span class=\"greek\">τοῦ</span> <span class=\"greek\">θεοῦ</span> os próprios elementos das verdades de Deus <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/HEB.5.12\" target=\"_blank\" rel=\"noopener noreferrer\">Hb 5:12</a>. Esta acepção também é provável nas passagens de Gal (4:3, 9 NEB ‘ideias elementares pertencentes a este mundo’; cf. LBelleville, JSNT 26, ’86, 53–78) e Col; v. a seguir.</p>\n<p class=\"entry-text\">② poderes transcendentes que governam os acontecimentos deste mundo, elementos, espíritos elementares. A acepção de <span class=\"greek\">στ</span>. em <span class=\"greek\">τὰ</span> <span class=\"greek\">στοιχεῖα</span> <span class=\"greek\">τοῦ</span> <span class=\"greek\">κόσμου</span> <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/GAL.4.3\" target=\"_blank\" rel=\"noopener noreferrer\">Gal 4:3</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/COL.2.8\" target=\"_blank\" rel=\"noopener noreferrer\">Col 2:8</a>, 20 (para a expressão <span class=\"greek\">στοιχ</span>. <span class=\"greek\">τ</span>. <span class=\"greek\">κόσμου</span> cf. SibOr 2, 206; 3, 80f; 8, 337) e <span class=\"greek\">τὰ</span> <span class=\"greek\">ἀσθενῆ</span> <span class=\"greek\">καὶ</span> <span class=\"greek\">πτωχὰ</span> <span class=\"greek\">στοιχεῖα</span> <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/GAL.4.9\" target=\"_blank\" rel=\"noopener noreferrer\">Gal 4:9</a> é muito discutida. Para uma visão de conjunto v. EBurton, ICC Gal 1921, 510–18. Alguns (p. ex., Burton, Goodsp.) preferem entendê-lo na acepção 1c acima, como referência às formas elementares de religião, judaicas e politeístas, que foram superadas pela nova revelação em Cristo (assim também WKnox, St. Paul and the Church of the Gentiles ’39, 108f; RGrant, HTR 39, ’46, 71–3; ACramer, Stoicheia Tou Kosmou, ’61 [as tendências não regeneradas no interior dos seres humanos]).—Outros (p. ex., WBauer, Mft., NRSV) sustentam que a referência é aos espíritos elementares que as tendências religiosas sincréticas da Antiguidade tardia associavam aos elementos físicos (Herm. Wr. <span class=\"greek\">Κόρη</span> <span class=\"greek\">κόσμου</span> em Stob. I 409 W.=Sc. 486ff, especialmente 486, 23; 25; 490, 14: os <span class=\"greek\">στοιχεῖα</span>, fogo, ar, água, terra, queixam-se à divindade que está acima de todos; Orph. Hymn. 5, 4; 66, 4 Qu.; Ps.-Callisth. 1, 3 [v. abaixo Pfister p. 416f]; Simplicius In Aristot. De Caelo 1, 3 p. 107, 15 Heiberg.—MDibelius, Geisterwelt 78ff; 228ff, Hdb. z. NT2 exc. sobre <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/COL.2.8\" target=\"_blank\" rel=\"noopener noreferrer\">Col 2:8</a>; ELohmeyer, Col 1930, 4–8; 103–5; FPfister, Die <span class=\"greek\">στοιχεῖα</span> <span class=\"greek\">τοῦ</span> <span class=\"greek\">κόσμου</span> in den Briefen des Ap. Pls: Philol. 69, 1910, 411–27; GMacgregor: ACPurdy Festschr. ’60, 88–104); às vezes eram adorados como divindades (Vett. Val. 293, 27; Philo, Vita Cont. 3 <span class=\"greek\">τοὺς</span> <span class=\"greek\">τὰ</span> <span class=\"greek\">στοιχεῖα</span> <span class=\"greek\">τιμῶντας</span>, <span class=\"greek\">γῆν</span>, <span class=\"greek\">ὕδωρ</span>, <span class=\"greek\">ἀέρα</span>, <span class=\"greek\">πῦρ</span>. Cf. Diels [v. abaixo] 45ff; Schweizer 1a acima). Nem sempre é fácil distinguir esta acepção da de 1b acima, pois os corpos celestes também eram considerados seres pessoais e recebiam honras divinas.—HDiels, Elementum 1899; ABonhöffer, Epiktet u. das NT 1911, 130ff; OLagercrantz, Elementum 1911 (p. 41 <span class=\"greek\">στοιχεῖα</span> <span class=\"greek\">τοῦ</span> <span class=\"greek\">κόσμου</span>=<span class=\"greek\">θεμέλια</span> <span class=\"greek\">τοῦ</span> <span class=\"greek\">κόσμου</span>); BEaston, The Pauline Theol. and Hellenism: AJT 21, 1917, 358–82; KDieterich, Hellenist. Volksreligion u. byz.-neugriech. Volksglaube: <span class=\"greek\">Αγγελος</span> I 1925, 2–23; sobre Gal 4 e Col 2, GKurze, D. <span class=\"greek\">στοιχεῖα</span> <span class=\"greek\">τ</span>. <span class=\"greek\">κόσμου</span>: BZ 15, 1927, 335; WHatch, <span class=\"greek\">Τὰ</span> <span class=\"greek\">στοιχεῖα</span> in Paul and Bardaisân: JTS 28, 1927, 181f; JHuby, <span class=\"greek\">Στοιχεῖα</span> dans Bardesane et dans St. Paul: Biblica 15, ’34, 365–68; sobre <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/GAL.4.3\" target=\"_blank\" rel=\"noopener noreferrer\">Gal 4:3</a>, 9 e <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/COL.2.8\" target=\"_blank\" rel=\"noopener noreferrer\">Col 2:8</a>, 20, LScheu, Die ‘Weltelemente’ beim Ap. Pls: diss. Cath. Univ., Washington ’34; BReicke, JBL 70, ’51, 259–76 (<a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/GAL.4.1\" target=\"_blank\" rel=\"noopener noreferrer\">Gal 4:1–11</a>); WBrownlee, Messianic Motifs of Qumran and the NT, NTS 3, ’56/57, 195–210; MKiley, SBLSP 25, ’86, 236–45.—RAC IV 1073–1100; B. 1501. DELG s.v. <span class=\"greek\">στείχω</span>. M-M. EDNT. TW. Sv.</p></section></article>\n<article class=\"entry-card\" id=\"entry-bdag-0332-08\" data-dictionary=\"grego\" hidden data-source=\"BDAG\"><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">στοιχέω</h1><div class=\"entry-meta\"><span>verbo</span></div></div><div class=\"source-tag\">BDAG</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Tradução integral</div><p class=\"entry-text\"><span class=\"greek\">στοιχέω</span> (<span class=\"greek\">στοῖχος</span>) futuro <span class=\"greek\">στοιχήσω</span> (X. et al.; inscrições, papiros; Eccl 11:6) originalmente ‘estar disposto em fila’, em nossa literatura somente em sentido figurado: estar em conformidade com uma pessoa ou coisa considerada padrão de conduta, ater-se a, concordar com, seguir, conformar-se, com dativo (Polyb. 28, 5, 6; Dionys. Hal. 6, 65; OGI 339, 51 [II d.C.]; SIG 685, 18; 734, 6; Michel 544, 14 <span class=\"greek\">βουλόμενος</span> <span class=\"greek\">στοιχεῖν</span> <span class=\"greek\">τοῖς</span> <span class=\"greek\">πρασσομένοις</span>; nos papiros somente a partir da época bizantina) <span class=\"greek\">ὅσοι</span> <span class=\"greek\">τῷ</span> <span class=\"greek\">κανόνι</span> <span class=\"greek\">τούτῳ</span> <span class=\"greek\">στοιχήσουσιν</span> todos os que seguirão esta regra <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/GAL.6.16\" target=\"_blank\" rel=\"noopener noreferrer\">Gal 6:16</a>; cf. <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/PHP.3.16\" target=\"_blank\" rel=\"noopener noreferrer\">Phil 3:16</a> variante de leitura; <span class=\"greek\">στ</span>. <span class=\"greek\">τῷ</span> <span class=\"greek\">λόγῳ</span> <span class=\"greek\">Ἰησοῦ</span> <span class=\"greek\">Χρ</span>. MPol 22:1. <span class=\"greek\">πνεύματι</span> <span class=\"greek\">στ</span>. seguir o Espírito <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/GAL.5.25\" target=\"_blank\" rel=\"noopener noreferrer\">Gal 5:25</a>. <span class=\"greek\">εἰς</span> <span class=\"greek\">ὸ̔</span> <span class=\"greek\">ἐφθάσαμεν</span>, <span class=\"greek\">τῷ</span> <span class=\"greek\">αὐτῷ</span> <span class=\"greek\">στοιχεῖν</span> devemos ater-nos ao que alcançamos <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/PHP.3.16\" target=\"_blank\" rel=\"noopener noreferrer\">Phil 3:16</a>. <span class=\"greek\">στ</span>. <span class=\"greek\">τοῖς</span> <span class=\"greek\">ἴχνεσίν</span> <span class=\"greek\">τινος</span> seja nossa conduta coerente com o que já alcançamos (assim REB; v. <span class=\"greek\">ἴχνος</span>) <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ROM.4.12\" target=\"_blank\" rel=\"noopener noreferrer\">Ro 4:12</a>.—Absolutamente (assim talvez OGI 308, 21) <span class=\"greek\">στοιχεῖς</span> <span class=\"greek\">φυλάσσων</span> <span class=\"greek\">τὸν</span> <span class=\"greek\">νόμον</span> <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ACT.21.24\" target=\"_blank\" rel=\"noopener noreferrer\">Ac 21:24</a> (o particípio indica aquilo a que Paulo se conforma).—New Docs 2, 97. DELG s.v. <span class=\"greek\">στείχω</span>. M-M. TW.</p></section></article>\n<article class=\"entry-card\" id=\"entry-bdag-0332-09\" data-dictionary=\"grego\" hidden data-source=\"BDAG\"><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">στοῖχος, ου, ὁ</h1><div class=\"entry-meta\"><span>substantivo masculino</span></div></div><div class=\"source-tag\">BDAG</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Tradução integral</div><p class=\"entry-text\"><span class=\"greek\">στοῖχος</span>, <span class=\"greek\">ου</span>, <span class=\"greek\">ὁ</span> (Hdt. et al.; inscrições; POxy 1119, 12; Philo, Op. M. 141; Jos., Ant. 15, 413) uma fileira numa série ascendente, fileira, fiada de alvenaria (assim SIG 970, 11) Hs 9, 4, 3.—DELG s.v. <span class=\"greek\">στείχω</span>.</p></section></article>\n<article class=\"entry-card\" id=\"entry-bdag-0332-10\" data-dictionary=\"grego\" hidden data-source=\"BDAG\"><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">στολή, ῆς, ἡ</h1><div class=\"entry-meta\"><span>substantivo feminino</span></div></div><div class=\"source-tag\">BDAG</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Tradução integral</div><p class=\"entry-text\"><span class=\"greek\">στολή</span>, <span class=\"greek\">ῆς</span>, <span class=\"greek\">ἡ</span> (<span class=\"greek\">στέλλω</span> ‘vestir’; Trag., X., Pla. et al.) especialmente uma veste longa e ampla (SIG 1025, 10; PEdg 9 [=Sb 6715], 32 [258 a.C.]; 44 [=Sb 6750], 4 e outras ocorrências em papiros; Ex 28:2; 2 Ch 18:9; Esth 6:8 e outras ocorrências na LXX; pseudepígrafos, Philo; Jos., Ant. 20, 7, Vi. 334; Just., A I, 32, 8; Tat., 24, 1; Mel., P. 17, 116 e outras ocorrências; empréstimo nos escritos rabínicos) <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/LUK.15.22\" target=\"_blank\" rel=\"noopener noreferrer\">Lk 15:22</a> (<span class=\"greek\">πρῶτος</span> 2a<span class=\"greek\">α</span>); <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/REV.7.14\" target=\"_blank\" rel=\"noopener noreferrer\">Rv 7:14</a>; 22:14 (sobre o uso metafórico em ambas as passagens v. <span class=\"greek\">πλύνω</span> 1). <span class=\"greek\">στολὴ</span> <span class=\"greek\">λευκή</span> (PGiss 20, 17) como a usada pelos anjos <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MRK.16.5\" target=\"_blank\" rel=\"noopener noreferrer\">Mk 16:5</a> e pelos fiéis glorificados <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/REV.6.11\" target=\"_blank\" rel=\"noopener noreferrer\">Rv 6:11</a>; 7:9, 13. <span class=\"greek\">στ</span>. <span class=\"greek\">λαμπροτάτη</span> GPt 13:55 (TestAbr A 16 p. 97, 8 [Stone p. 42]; cf. a veste sagrada do sacerdote SIG 1025, 10). Dos escribas <span class=\"greek\">ἐν</span> <span class=\"greek\">στολαῖς</span> <span class=\"greek\">περιπατεῖν</span> andar de vestes longas (M. Ant. 1, 7, 4 <span class=\"greek\">ἐν</span> <span class=\"greek\">στολίῳ</span> [variante de leitura <span class=\"greek\">στολῇ</span>] <span class=\"greek\">περιπατεῖν</span>) <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MRK.12.38\" target=\"_blank\" rel=\"noopener noreferrer\">Mk 12:38</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/LUK.20.46\" target=\"_blank\" rel=\"noopener noreferrer\">Lk 20:46</a> (das vestes sacerdotais Philo, Leg. ad Gai. 296; Jos., Ant. 3, 151; 11, 80).—KRengstorf, OMichel Festschr., ’63, 383–404. DELG s.v. <span class=\"greek\">στέλλω</span>. TW.</p></section></article>\n<article class=\"entry-card\" id=\"entry-bdag-0332-11\" data-dictionary=\"grego\" hidden data-source=\"BDAG\"><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">στόμα, ατος, τό</h1><div class=\"entry-meta\"><span>substantivo neutro</span></div></div><div class=\"source-tag\">BDAG</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Tradução integral</div><p class=\"entry-text\"><span class=\"greek\">στόμα</span>, <span class=\"greek\">ατος</span>, <span class=\"greek\">τό</span> (Hom.+; empréstimo nos escritos rabínicos).</p>\n<p class=\"entry-text\">① boca</p>\n<p class=\"entry-text\">ⓐ de seres humanos ou de seres cuja aparência se assemelha à humana: <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MAT.15.11\" target=\"_blank\" rel=\"noopener noreferrer\">Mt 15:11a</a>, 17; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/JHN.19.29\" target=\"_blank\" rel=\"noopener noreferrer\">J 19:29</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ACT.11.8\" target=\"_blank\" rel=\"noopener noreferrer\">Ac 11:8</a>; 23:2; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/2TH.2.8\" target=\"_blank\" rel=\"noopener noreferrer\">2 Th 2:8</a> (cf. Is 11:4; Ps 32:6); <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/REV.11.5\" target=\"_blank\" rel=\"noopener noreferrer\">Rv 11:5</a>.—Usado em linguagem figurada <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/REV.1.16\" target=\"_blank\" rel=\"noopener noreferrer\">Rv 1:16</a>; 2:16; 3:16; 10:9f (cf. Ezk 3:1ff); 19:15, 21.—Como órgão da fala <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MAT.15.11\" target=\"_blank\" rel=\"noopener noreferrer\">Mt 15:11b</a>, 18 (cf. Num 32:24); 21:16 (Ps 8:3); <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/LUK.4.22\" target=\"_blank\" rel=\"noopener noreferrer\">Lk 4:22</a>; 11:54; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ROM.10.8\" target=\"_blank\" rel=\"noopener noreferrer\">Ro 10:8</a> (Dt 30:14); <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/EPH.4.29\" target=\"_blank\" rel=\"noopener noreferrer\">Eph 4:29</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/JAS.3.10\" target=\"_blank\" rel=\"noopener noreferrer\">Js 3:10</a> (cf. Aesop, Fab. 35 P.=64 H.//60 Ch.//35 H-H.: <span class=\"greek\">ἐκ</span> <span class=\"greek\">τοῦ</span> <span class=\"greek\">αὐτοῦ</span> <span class=\"greek\">στόματος</span> <span class=\"greek\">τὸ</span> <span class=\"greek\">θερμὸν</span> <span class=\"greek\">καὶ</span> <span class=\"greek\">τὸ</span> <span class=\"greek\">ψυχρὸν</span> <span class=\"greek\">ἐξιεῖς</span>=da mesma boca fazes sair calor e frio [da pessoa que sopra nas mãos para aquecê-las e na comida para esfriá-la]); 1 Cl 15:3 (Ps 61:5), 4 (Ps 77:36); 2 Cl 9:10; B 11:8; Hm 3:1. <span class=\"greek\">ἀπόθεσθε</span> <span class=\"greek\">αἰσχρολογίαν</span> <span class=\"greek\">ἐκ</span> <span class=\"greek\">τοῦ</span> <span class=\"greek\">στόματος</span> <span class=\"greek\">ὑμῶν</span> afastai de vossa boca a linguagem vergonhosa = não permitais que palavras obscenas saiam de vossos lábios <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/COL.3.8\" target=\"_blank\" rel=\"noopener noreferrer\">Col 3:8</a>. <span class=\"greek\">ἀκούειν</span> <span class=\"greek\">τι</span> <span class=\"greek\">ἐκ</span> <span class=\"greek\">τοῦ</span> <span class=\"greek\">στόματός</span> <span class=\"greek\">τινος</span> <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ACT.22.14\" target=\"_blank\" rel=\"noopener noreferrer\">Ac 22:14</a>; 2 Cl 13:3; B 16:10 (cf. ParJer 6:24); <span class=\"greek\">ἀκ</span>. <span class=\"greek\">ἀπὸ</span> <span class=\"greek\">τοῦ</span> <span class=\"greek\">στ</span>. <span class=\"greek\">τινος</span> (Polyaenus 8, 36 <span class=\"greek\">ἀπὸ</span> <span class=\"greek\">στόματος</span> <span class=\"greek\">τῆς</span> <span class=\"greek\">ἀδελφῆς</span>) <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/LUK.22.71\" target=\"_blank\" rel=\"noopener noreferrer\">Lk 22:71</a>; <span class=\"greek\">ἀκ</span>. <span class=\"greek\">τι</span> <span class=\"greek\">διὰ</span> <span class=\"greek\">τοῦ</span> <span class=\"greek\">στ</span>. <span class=\"greek\">τινος</span> <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ACT.1.4\" target=\"_blank\" rel=\"noopener noreferrer\">Ac 1:4</a> D; 15:7.—<span class=\"greek\">ἀνεῴχθη</span> <span class=\"greek\">τὸ</span> <span class=\"greek\">στ</span>. <span class=\"greek\">αὐτοῦ</span> (de uma pessoa muda) abriu-se-lhe a boca (Wsd 10:21) <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/LUK.1.64\" target=\"_blank\" rel=\"noopener noreferrer\">Lk 1:64</a>, as palavras agora podiam sair, como traduz a REB: ‘seus lábios e sua língua foram libertados’. <span class=\"greek\">ἀνοίγειν</span> <span class=\"greek\">τὸ</span> <span class=\"greek\">στόμα</span> <span class=\"greek\">τινός</span> abrir a boca de alguém e fazê-lo falar 1 Cl 18:15 (cf. Ps 50:17). <span class=\"greek\">ἀνοίγειν</span> <span class=\"greek\">τὸ</span> (<span class=\"greek\">ἑαυτοῦ</span>) <span class=\"greek\">στόμα</span> abrir a (própria) boca para falar (ApcMos 21; ApcrEzk; v. <span class=\"greek\">ἀνοίγω</span> 5a) <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MAT.5.2\" target=\"_blank\" rel=\"noopener noreferrer\">Mt 5:2</a>; 13:35 (Ps 77:2); <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ACT.8.35\" target=\"_blank\" rel=\"noopener noreferrer\">Ac 8:35</a>; 10:34; 18:14; GEb 34:60. <span class=\"greek\">οὐκ</span> <span class=\"greek\">ἀνοίγει</span> <span class=\"greek\">τὸ</span> <span class=\"greek\">στ</span>. <span class=\"greek\">αὐτοῦ</span>=permanece calado <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ACT.8.32\" target=\"_blank\" rel=\"noopener noreferrer\">Ac 8:32</a>; 1 Cl 16:7 (ambos Is 53:7; cf. Mel., P. 64; 462). Para <span class=\"greek\">ἄνοιξις</span> <span class=\"greek\">τοῦ</span> <span class=\"greek\">στόματος</span> <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/EPH.6.19\" target=\"_blank\" rel=\"noopener noreferrer\">Eph 6:19</a> v. <span class=\"greek\">ἄνοιξις</span>. Sobre <span class=\"greek\">στόμα</span> <span class=\"greek\">πρὸς</span> <span class=\"greek\">στόμα</span> <span class=\"greek\">λαλεῖν</span> falar face a face 2J 12; 3J 14 v. <span class=\"greek\">πρός</span> 3a<span class=\"greek\">ε</span>. Sobre <span class=\"greek\">ἵνα</span> <span class=\"greek\">πᾶν</span> <span class=\"greek\">στ</span>. <span class=\"greek\">φραγῇ</span> <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ROM.3.19\" target=\"_blank\" rel=\"noopener noreferrer\">Ro 3:19</a> v. <span class=\"greek\">φράσσω</span>.—Não há <span class=\"greek\">δόλος</span> nem <span class=\"greek\">ψεῦδος</span> na boca dos retos <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/REV.14.5\" target=\"_blank\" rel=\"noopener noreferrer\">Rv 14:5</a>; 1 Cl 50:6 (Ps 31:2); especialmente do ‘Servo’ de Deus (Is 53:9) <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/1PE.2.22\" target=\"_blank\" rel=\"noopener noreferrer\">1 Pt 2:22</a>; 1 Cl 16:10; Pol 8:1.—<span class=\"greek\">στόμα</span> representa a pessoa na qualidade de falante (3 Km 17:24; 22:22; 2 Ch 36:21f): <span class=\"greek\">ἐκ</span> <span class=\"greek\">τοῦ</span> <span class=\"greek\">περισσεύματος</span> <span class=\"greek\">τῆς</span> <span class=\"greek\">καρδίας</span> <span class=\"greek\">τὸ</span> <span class=\"greek\">στόμα</span> <span class=\"greek\">λαλεῖ</span> <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MAT.12.34\" target=\"_blank\" rel=\"noopener noreferrer\">Mt 12:34</a> (<span class=\"greek\">καρδία</span> … <span class=\"greek\">στ</span>. como em TestNapht 2:6). <span class=\"greek\">διὰ</span> <span class=\"greek\">στόματός</span> <span class=\"greek\">τινος</span> (ApcMos 16f; B-D-F §140) por (meio dos lábios de) alguém <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/LUK.1.70\" target=\"_blank\" rel=\"noopener noreferrer\">Lk 1:70</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ACT.1.16\" target=\"_blank\" rel=\"noopener noreferrer\">Ac 1:16</a>; 3:18, 21.—<span class=\"greek\">ἐν</span> <span class=\"greek\">ἑνὶ</span> <span class=\"greek\">στόματι</span> a uma só voz (<span class=\"greek\">ἓν</span> <span class=\"greek\">στόμα</span> Aristoph., Equ. 670; Pla., Rep. 364a, Laws 1, 634e; Ael. Aristid. 51, 40 K.=I p. 544 D.; PGiss 36, 12 [161 a.C.] <span class=\"greek\">αἱ</span> <span class=\"greek\">τέτταρες</span> <span class=\"greek\">λέγουσαι</span> <span class=\"greek\">ἐξ</span> <span class=\"greek\">ἑνὸς</span> <span class=\"greek\">στόματος</span>; Pla., Rep. 364a) <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ROM.15.6\" target=\"_blank\" rel=\"noopener noreferrer\">Ro 15:6</a>; cf. 1 Cl 34:7.—Para <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MAT.18.16\" target=\"_blank\" rel=\"noopener noreferrer\">Mt 18:16</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/2CO.13.1\" target=\"_blank\" rel=\"noopener noreferrer\">2 Cor 13:1</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/LUK.19.22\" target=\"_blank\" rel=\"noopener noreferrer\">Lk 19:22</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/LUK.21.15\" target=\"_blank\" rel=\"noopener noreferrer\">Lk 21:15</a> v. 2.</p>\n<p class=\"entry-text\">ⓑ de Deus (Dexippus de Atenas [III d.C.]: 100 Fgm. 1, 7 Jac. <span class=\"greek\">ἡ</span> <span class=\"greek\">τοῦ</span> <span class=\"greek\">θεοῦ</span> <span class=\"greek\">μαρτυρία</span> <span class=\"greek\">διὰ</span> <span class=\"greek\">στόματος</span>; Theognis18; ParJer 6:12) <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MAT.4.4\" target=\"_blank\" rel=\"noopener noreferrer\">Mt 4:4</a> (Dt 8:3); 1 Cl 8:4 (Is 1:20).</p>\n<p class=\"entry-text\">ⓒ de animais e seres semelhantes a animais, boca, fauces, de um peixe (PGM 5, 280ff) <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MAT.17.27\" target=\"_blank\" rel=\"noopener noreferrer\">Mt 17:27</a>. De cavalos <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/JAS.3.3\" target=\"_blank\" rel=\"noopener noreferrer\">Js 3:3</a>; cf. <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/REV.9.17\" target=\"_blank\" rel=\"noopener noreferrer\">Rv 9:17–9</a>; uma doninha B 10:8; leão (Judg 14:8) <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/HEB.11.33\" target=\"_blank\" rel=\"noopener noreferrer\">Hb 11:33</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/REV.13.2\" target=\"_blank\" rel=\"noopener noreferrer\">Rv 13:2</a>; em linguagem figurada <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/2TI.4.17\" target=\"_blank\" rel=\"noopener noreferrer\">2 Ti 4:17</a>; um monstro apocalíptico (Diod S 3, 70, 4 a Égide: <span class=\"greek\">ἐκ</span> <span class=\"greek\">τοῦ</span> <span class=\"greek\">στόματος</span> <span class=\"greek\">ἐκβάλλον</span> <span class=\"greek\">φλόγα</span>) <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/REV.12.15\" target=\"_blank\" rel=\"noopener noreferrer\">Rv 12:15</a>, 16b; 16:13abc; Hv 4, 1, 6; 4, 2, 4 (cf. Da 6:22 Theod.; JosAs 12:10).</p>\n<p class=\"entry-text\">② o produto do órgão da fala, enunciação, boca. Por metonímia, daquilo que a boca profere <span class=\"greek\">ἐπὶ</span> <span class=\"greek\">στόματος</span> <span class=\"greek\">δύο</span> <span class=\"greek\">μαρτύρων</span> (Dt 19:15) <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MAT.18.16\" target=\"_blank\" rel=\"noopener noreferrer\">Mt 18:16</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/2CO.13.1\" target=\"_blank\" rel=\"noopener noreferrer\">2 Cor 13:1</a>. <span class=\"greek\">ἐκ</span> <span class=\"greek\">τοῦ</span> <span class=\"greek\">στόματός</span> <span class=\"greek\">σου</span> <span class=\"greek\">κρινῶ</span> <span class=\"greek\">σε</span> <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/LUK.19.22\" target=\"_blank\" rel=\"noopener noreferrer\">Lk 19:22</a>. <span class=\"greek\">ἐγὼ</span> <span class=\"greek\">δώσω</span> <span class=\"greek\">ὑμῖν</span> <span class=\"greek\">στόμα</span> <span class=\"greek\">καὶ</span> <span class=\"greek\">σοφίαν</span> dar-vos-ei eloquência e sabedoria <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/LUK.21.15\" target=\"_blank\" rel=\"noopener noreferrer\">Lk 21:15</a>. V. também 1a.</p>\n<p class=\"entry-text\">③ uma fissura geológica, boca, na imagem da terra em que se abre uma fissura (v. Gen 4:11) <span class=\"greek\">ἤνοιξεν</span> <span class=\"greek\">ἡ</span> <span class=\"greek\">γῆ</span> <span class=\"greek\">τὸ</span> <span class=\"greek\">στόμα</span> <span class=\"greek\">αὐτῆς</span> <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/REV.12.16\" target=\"_blank\" rel=\"noopener noreferrer\">Rv 12:16a</a>.</p>\n<p class=\"entry-text\">④ a parte dianteira de algo, fio, extensão figurada de 1. A espada, como as fauces de um animal selvagem, devora pessoas; daí, conforme o uso do AT (mas v. Philostrat., Her. 19, 4 <span class=\"greek\">στ</span>. <span class=\"greek\">τῆς</span> <span class=\"greek\">αἰχμῆς</span>; Quint. Smyrn. 1, 194; 813 e v. <span class=\"greek\">μάχαιρα</span> 1; cf. <span class=\"greek\">στ</span>.=‘ponta’ de uma espada Hom. et al.; <span class=\"greek\">στόμα</span> <span class=\"greek\">πολέμου</span> Polemo Soph. B8 Reader p. 134) <span class=\"greek\">στόμα</span> <span class=\"greek\">μαχαίρης</span> o fio da espada = a espada voraz (Josh 19:48; Sir 28:18; v. também <span class=\"greek\">μάχαιρα</span> 1, final) <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/LUK.21.24\" target=\"_blank\" rel=\"noopener noreferrer\">Lk 21:24</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/HEB.11.34\" target=\"_blank\" rel=\"noopener noreferrer\">Hb 11:34</a>.—B. 228; especialmente 860. DELG. M-M. TW.</p></section></article>\n<article class=\"entry-card\" id=\"entry-bdag-0332-12\" data-dictionary=\"grego\" hidden data-source=\"BDAG\"><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">στόμαχος, ου, ὁ</h1><div class=\"entry-meta\"><span>substantivo masculino</span></div></div><div class=\"source-tag\">BDAG</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Tradução integral</div><p class=\"entry-text\"><span class=\"greek\">στόμαχος</span>, <span class=\"greek\">ου</span>, <span class=\"greek\">ὁ</span> (Hom. et al., acepção original ‘garganta’; TestSol 18:18, 21; Philo; TestNapht 2:8; empréstimo nos escritos rabínicos) estômago (assim Plut., Mor. 698ab; Epict. 2, 20, 33; Athen. 3, 79e; PGM 13, 830) <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/1TI.5.23\" target=\"_blank\" rel=\"noopener noreferrer\">1 Ti 5:23</a>.—DELG s.v. <span class=\"greek\">στόμα</span>. M-M. Spicq.</p></section></article>\n<article class=\"entry-card\" id=\"entry-bdag-0332-13\" data-dictionary=\"grego\" hidden data-source=\"BDAG\"><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">στραγγαλιά, ᾶς, ἡ</h1><div class=\"entry-meta\"><span>substantivo feminino</span></div></div><div class=\"source-tag\">BDAG</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Tradução integral</div><p class=\"entry-text\"><span class=\"greek\">στραγγαλιά</span>, <span class=\"greek\">ᾶς</span>, <span class=\"greek\">ἡ</span> (Ptolem., Apotel. 4, 9, 10 Boll-B.; Hippiatr. 51, 3; 4, vol. I 228, 9; 229, 7; LXX) nó <span class=\"greek\">διαλύειν</span> <span class=\"greek\">στραγγαλιὰς</span> <span class=\"greek\">βιαίων</span> <span class=\"greek\">συναλλαγμάτων</span> desatar os nós dos acordos forçados (isto é, celebrados sob coação) B 3:3 (Is 58:6; cf. Plut., Mor. 1033e sobre os argumentos intrincados dos filósofos).</p></section></article>\n<article class=\"entry-card\" id=\"entry-bdag-0332-14\" data-dictionary=\"grego\" hidden data-source=\"BDAG\"><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">στραγγαλόω</h1><div class=\"entry-meta\"><span>verbo</span></div></div><div class=\"source-tag\">BDAG</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Tradução integral</div><p class=\"entry-text\"><span class=\"greek\">στραγγαλόω</span> 1 aoristo passivo <span class=\"greek\">ἐστραγγαλώθην</span>; particípio perfeito passivo <span class=\"greek\">ἐστραγγαλωμένος</span> Tob 2:3 BA (Philo Mech. 57, 42; Alex. Aphr., Probl. 1, 76 Ideler) estrangular (Tob 2:3 BA), passivo, com sentido intransitivo, sufocar-se ITr 5:1.—DELG s.v. <span class=\"greek\">στράγξ</span>.</p></section></article>\n<article class=\"entry-card\" id=\"entry-bdag-0332-15\" data-dictionary=\"grego\" hidden data-source=\"BDAG\"><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">στρατεία, ας, ἡ</h1><div class=\"entry-meta\"><span>substantivo feminino</span></div></div><div class=\"source-tag\">BDAG</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Tradução integral</div><p class=\"entry-text\"><span class=\"greek\">στρατεία</span>, <span class=\"greek\">ας</span>, <span class=\"greek\">ἡ</span> (<span class=\"greek\">στρατεύω</span>; Aeschyl., Hdt.+; inscrições, papiros, LXX; TestSol 10:36 C; Jos., Bell. 3, 445, Ant. 16, 343. Sobre a grafia v. Dssm., NB 9f [BS 181f]; B-D-F §23; Mlt-H. 78) atividade militar, expedição, campanha, em linguagem figurada (Epict. 3, 24, 34 <span class=\"greek\">στρατεία</span> <span class=\"greek\">τίς</span> <span class=\"greek\">ἐστιν</span> <span class=\"greek\">ὁ</span> <span class=\"greek\">βίος</span> <span class=\"greek\">ἑκάστου</span>; Maximus Tyr. 13, 4d) <span class=\"greek\">τὰ</span> <span class=\"greek\">ὅπλα</span> <span class=\"greek\">τῆς</span> <span class=\"greek\">στρατείας</span> <span class=\"greek\">ἡμῶν</span> as armas que usamos em nossa guerra <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/2CO.10.4\" target=\"_blank\" rel=\"noopener noreferrer\">2 Cor 10:4</a> (a variante de leitura <span class=\"greek\">στρατίας</span> é itacismo: W-S. §5 A 31). <span class=\"greek\">στρατεύεσθαι</span> <span class=\"greek\">τὴν</span> <span class=\"greek\">καλὴν</span> <span class=\"greek\">στρατείαν</span> combater o bom combate <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/1TI.1.18\" target=\"_blank\" rel=\"noopener noreferrer\">1 Ti 1:18</a> (para <span class=\"greek\">στρατεύεσθαι</span> <span class=\"greek\">στρ</span>. cf. Isaeus 10, 25; Aeschin. 2, 169; Plut., Mor. 204a; Epict. 2, 14, 17 (MAdinolfi, Le imagini militari nelle diatribe de Epitteto un confronto con l’epistolario Paolino, in Atti del IV Simposio di Tarso su S. Paolo Apostolo, ed. LPadovese ’96, 59–72); SIG 346, 55; 4 Macc 9:24; Philo, Leg. All. 3, 14).—Sobre a vida cristã como serviço militar v. <span class=\"greek\">πανοπλία</span> 2.—DELG s.v. <span class=\"greek\">στρατό</span>. M-M. TW.</p></section></article>\n<article class=\"entry-card\" id=\"entry-bdag-0332-16\" data-dictionary=\"grego\" hidden data-source=\"BDAG\"><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">στράτευμα, ατος, τό</h1><div class=\"entry-meta\"><span>substantivo neutro</span></div></div><div class=\"source-tag\">BDAG</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Tradução integral</div><p class=\"entry-text\"><span class=\"greek\">στράτευμα</span>, <span class=\"greek\">ατος</span>, <span class=\"greek\">τό</span> uma força militar, exército (assim Trag., Hdt. et al.; inscrições, papiros, LXX; TestJob 30:2 e outras ocorrências [tropas] EpArist 37; Philo; Jos., Bell. 3, 162, Ant. 4, 94) singular <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/REV.19.19\" target=\"_blank\" rel=\"noopener noreferrer\">Rv 19:19b</a>; plural 19:14, 19a.—De um destacamento menor de soldados, singular <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ACT.23.10\" target=\"_blank\" rel=\"noopener noreferrer\">Ac 23:10</a>, 27.—<span class=\"greek\">τὰ</span> <span class=\"greek\">στρατεύματα</span> as tropas (4 Macc 5:1; Jos., Ant. 13, 131. V. AVerrall, JTS 10, 1909, 340f) <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MAT.22.7\" target=\"_blank\" rel=\"noopener noreferrer\">Mt 22:7</a> (MBlack, An Aramaic Approach3, ’67, 128); <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/LUK.23.11\" target=\"_blank\" rel=\"noopener noreferrer\">Lk 23:11</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/REV.9.16\" target=\"_blank\" rel=\"noopener noreferrer\">Rv 9:16</a>.—B. 1377. DELG s.v. <span class=\"greek\">στρατό</span>. M-M. TW.</p></section></article>\n<article class=\"entry-card\" id=\"entry-bdag-0332-17\" data-dictionary=\"grego\" hidden data-source=\"BDAG\"><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">στρατεύω</h1><div class=\"entry-meta\"><span>verbo</span></div></div><div class=\"source-tag\">BDAG</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Tradução integral</div><p class=\"entry-text\"><span class=\"greek\">στρατεύω</span> (variavelmente na voz ativa ou média desde Aeschyl., Hdt. et al.; inscrições, papiros, LXX, ApkEzk [Epiph 70, 6], Tat.) em nossa literatura sempre um depoente médio <span class=\"greek\">στρατεύομαι</span> 1 aoristo <span class=\"greek\">ἐστρατευσάμην</span>; infinitivo médio-passivo (v. Schwyzer I 639, II 237f; B-D-F §87) <span class=\"greek\">στρατευθῆναι</span> (AcPl Ha 9, 6 restaurado)</p>\n<p class=\"entry-text\">① prestar serviço militar, servir no exército (X., Mem. 1, 6, 9; BGU 1097, 8 [I d.C.]; Jos., Bell. 2, 520, Ant. 17, 270, Vi. 346; Tat.) <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/2TI.2.4\" target=\"_blank\" rel=\"noopener noreferrer\">2 Ti 2:4</a>; 1 Cl 37:2. <span class=\"greek\">στ</span>. <span class=\"greek\">ἰδίοις</span> <span class=\"greek\">ὀψωνίοις</span> servir como soldado à própria custa <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/1CO.9.7\" target=\"_blank\" rel=\"noopener noreferrer\">1 Cor 9:7</a>. <span class=\"greek\">στρατευόμενοι</span>=soldados (Thu. 8, 65, 3; Plut., Mor. 274a; Appian, Bell. Civ. 3, 41 §168; 3, 90 §371; Sb 8008, 49 [261 a.C.]) <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/LUK.3.14\" target=\"_blank\" rel=\"noopener noreferrer\">Lk 3:14</a> (SMcCasland, JBL 62, ’43, 59–71).</p>\n<p class=\"entry-text\">② empenhar-se num conflito, travar batalha, combater, extensão figurada de 1 (Lucian, Vit. Auct. 8 <span class=\"greek\">ἐπὶ</span> <span class=\"greek\">τὰς</span> <span class=\"greek\">ἡδονάς</span>) dos cristãos 1 Cl 37:1; com o dativo, por Deus, Cristo IPol 6:2; AcPl Ha 9, 6f; da atividade do apóstolo <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/2CO.10.3\" target=\"_blank\" rel=\"noopener noreferrer\">2 Cor 10:3</a>. Sobre <span class=\"greek\">στρατεύεσθαι</span> <span class=\"greek\">τὴν</span> <span class=\"greek\">καλὴν</span> <span class=\"greek\">στρατείαν</span> <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/1TI.1.18\" target=\"_blank\" rel=\"noopener noreferrer\">1 Ti 1:18</a> v. <span class=\"greek\">στρατεία</span>. Das lutas das paixões no interior da alma humana <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/JAS.4.1\" target=\"_blank\" rel=\"noopener noreferrer\">Js 4:1</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/1PE.2.11\" target=\"_blank\" rel=\"noopener noreferrer\">1 Pt 2:11</a>; Pol 5:3.—DELG s.v. <span class=\"greek\">στρατό</span>. M-M. TW.</p></section></article>\n<article class=\"entry-card\" id=\"entry-bdag-0332-18\" data-dictionary=\"grego\" hidden data-source=\"BDAG\"><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">στρατηγός, οῦ, ὁ</h1><div class=\"entry-meta\"><span>substantivo masculino</span></div></div><div class=\"source-tag\">BDAG</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Tradução integral</div><p class=\"entry-text\"><span class=\"greek\">στρατηγός</span>, <span class=\"greek\">οῦ</span>, <span class=\"greek\">ὁ</span> (<span class=\"greek\">στρατός</span> ‘exército, hoste’, <span class=\"greek\">ἄγω</span>; Aeschyl., Hdt.+; inscrições, papiros, LXX; EpArist 280; Philo, Joseph.; Mel., P. 105, 818; empréstimo nos escritos rabínicos. Originalmente ‘general’).</p>\n<p class=\"entry-text\">① o mais alto funcionário de uma cidade greco-romana, pretor, magistrado supremo, plural dos mais altos funcionários da colônia romana de Filipos. Este título não era inteiramente correto do ponto de vista oficial, pois esses homens eram propriamente denominados ‘duoviri’, mas ocorre várias vezes nas inscrições como designação popular deles (JWeiss, RE XII 1903, p. 39, 39f.—<span class=\"greek\">στρατηγοί</span> governavam Pérgamo [Jos., Ant. 14, 247] e Sardes [14, 259]) <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ACT.16.20\" target=\"_blank\" rel=\"noopener noreferrer\">Ac 16:20</a>, 22, 35f, 38.—Mommsen, Röm. Geschichte V 274ff; JMarquardt, Staatsverw. I2 1881, 316ff; Ramsay, JTS 1, 1900, 114–16; FHaverfield, ibid. 434f; Zahn, Einl.3 I 378ff; AWikenhauser, Die AG 1921, 346f. Mason 86f.</p>\n<p class=\"entry-text\">② <span class=\"greek\">ὁ</span> <span class=\"greek\">στρατηγὸς</span> <span class=\"greek\">τοῦ</span> <span class=\"greek\">ἱεροῦ</span>=comandante responsável pelo templo de Jerusalém, capitão do templo <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ACT.4.1\" target=\"_blank\" rel=\"noopener noreferrer\">Ac 4:1</a>; 5:24. Também simplesmente <span class=\"greek\">ὁ</span> <span class=\"greek\">στρατηγός</span> (Jos., Bell. 6, 294, Ant. 20, 131) versículo 26. No plural (LXX; v. Schürer II 278, 7) <span class=\"greek\">στρατηγοὶ</span> (<span class=\"greek\">τοῦ</span> <span class=\"greek\">ἱεροῦ</span>) <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/LUK.22.4\" target=\"_blank\" rel=\"noopener noreferrer\">Lk 22:4</a>, 52.—Schürer II 277f e v. EBriess, WienerStud 34, 1912, 356f; Kl. Pauly V 388–91 (CIG 3151 <span class=\"greek\">στ</span>. <span class=\"greek\">ἐπὶ</span> <span class=\"greek\">τοῦ</span> <span class=\"greek\">ἱεροῦ</span>).—B. 1381f. DELG s.v. <span class=\"greek\">στρατό</span>. M-M. TW.</p></section></article>\n<article class=\"entry-card\" id=\"entry-bdag-0332-19\" data-dictionary=\"grego\" hidden data-source=\"BDAG\"><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">στρατιά, ᾶς, ἡ</h1><div class=\"entry-meta\"><span>substantivo feminino</span></div></div><div class=\"source-tag\">BDAG</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Tradução integral</div><p class=\"entry-text\"><span class=\"greek\">στρατιά</span>, <span class=\"greek\">ᾶς</span>, <span class=\"greek\">ἡ</span></p>\n<p class=\"entry-text\">① exército (assim Pind., Hdt.+; inscrições, papiros, LXX, TestAbr A 2 p. 78, 28 [Stone p. 4]; JosAs 14:7 [<span class=\"greek\">τοῦ</span> <span class=\"greek\">ὐψίστου</span>]; ApcEsdr 6:16f p. 31, 23 Tdf. [<span class=\"greek\">ἀγγέλων</span>]; ApcMos 38 [<span class=\"greek\">κύριος</span> <span class=\"greek\">στρατιῶν</span>]; Philo; Jos., Bell. 7, 31, Ant. 14, 271; Just.; empréstimo nos escritos rabínicos) do exército do faraó 1 Cl 51:5 (cf. Ex 14:4, 9, 17).—<span class=\"greek\">στρατιὰ</span> <span class=\"greek\">οὐράνιος</span> o exército celestial de anjos (v. 3 Km 22:19; 2 Esdr 19: 6.—Pla., Phdr. 246e <span class=\"greek\">στρατιὰ</span> <span class=\"greek\">θεῶν</span> <span class=\"greek\">τε</span> <span class=\"greek\">καὶ</span> <span class=\"greek\">δαιμόνων</span>; Just., D. 131, 2 <span class=\"greek\">τοῦ</span> <span class=\"greek\">διαβόλου</span>) <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/LUK.2.13\" target=\"_blank\" rel=\"noopener noreferrer\">Lk 2:13</a> (para a construção ad sensum <span class=\"greek\">πλῆθος</span> <span class=\"greek\">στρατιᾶς</span> … <span class=\"greek\">αἰνούντων</span> cf. Appian, Bell. Civ. 5, 64 §272 <span class=\"greek\">ὁ</span> <span class=\"greek\">στρατὸς</span> <span class=\"greek\">αἰσθανόμενοι</span> <span class=\"greek\">εἵλοντο</span>). <span class=\"greek\">ἡ</span> <span class=\"greek\">στρατιὰ</span> <span class=\"greek\">τοῦ</span> <span class=\"greek\">οὐρανοῦ</span> a hoste do céu, dos corpos celestes (cf. Ps.-Demetr. c. 91 segundo um antigo poeta lírico <span class=\"greek\">ἄστρων</span> <span class=\"greek\">στρατόν</span>; Maximus Tyr. 13, 6e; 2 Ch 33:3, 5; Jer 8:2; PGM 35, 13) <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ACT.7.42\" target=\"_blank\" rel=\"noopener noreferrer\">Ac 7:42</a>.</p>\n<p class=\"entry-text\">② ocasionalmente (poetas, papiros) na mesma acepção que <span class=\"greek\">στρατεία</span> <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/2CO.10.4\" target=\"_blank\" rel=\"noopener noreferrer\">2 Cor 10:4</a> variante de leitura, mas v. <span class=\"greek\">στρατεία</span> sobre esta passagem.—DELG s.v. <span class=\"greek\">στρατός</span>. M-M. TW.</p></section></article>\n<article class=\"entry-card\" id=\"entry-bdag-0332-20\" data-dictionary=\"grego\" hidden data-source=\"BDAG\"><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">στρατιώτης, ου, ὁ</h1><div class=\"entry-meta\"><span>substantivo masculino</span></div></div><div class=\"source-tag\">BDAG</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Tradução integral</div><p class=\"entry-text\"><span class=\"greek\">στρατιώτης</span>, <span class=\"greek\">ου</span>, <span class=\"greek\">ὁ</span> (Aristoph., Hdt.+; empréstimo nos escritos rabínicos) soldado.</p>\n<p class=\"entry-text\">ⓐ literalmente <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MAT.8.9\" target=\"_blank\" rel=\"noopener noreferrer\">Mt 8:9</a>; 27:27; 28:12; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MRK.15.16\" target=\"_blank\" rel=\"noopener noreferrer\">Mk 15:16</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/LUK.7.8\" target=\"_blank\" rel=\"noopener noreferrer\">Lk 7:8</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/JHN.19.2\" target=\"_blank\" rel=\"noopener noreferrer\">J 19:2</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ACT.10.7\" target=\"_blank\" rel=\"noopener noreferrer\">Ac 10:7</a>; 28:16; GPt 8:30–32 e outras ocorrências; AcPl Ha 10, 28.</p>\n<p class=\"entry-text\">ⓑ figuradamente, mas com o componente principal de fidelidade a um comandante, presente na acepção central de ‘soldado’, como aspecto definidor <span class=\"greek\">στ</span>. <span class=\"greek\">Χριστοῦ</span> <span class=\"greek\">Ἰησοῦ</span> um soldado de Cristo Jesus <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/2TI.2.3\" target=\"_blank\" rel=\"noopener noreferrer\">2 Ti 2:3</a>; AcPl Ha 8, 9; cf. <span class=\"greek\">ὁ</span> <span class=\"greek\">τοῦ</span> <span class=\"greek\">θεοῦ</span> <span class=\"greek\">στ</span>. 11, 6 (sobre a ideia cf. a bibliografia s.v. <span class=\"greek\">πανοπλία</span> 2 e v. PGM 4, 193).—B. 1380. DELG s.v. <span class=\"greek\">στρατό</span>. M-M. TW.</p></section></article>"};
